results.harness:
# Real function: generate_commands
# Category: invalid_precondition
# Assume: abs(kind) <= 1073741824 is only a loose magnitude bound.
# Assert: result reports that to_remove supports the real membership test.
# Nondet operands: to_remove is a string stand-in; kind models its external type
# (0 = string, otherwise None). The real function enforces no preconditions.

def slice_model(to_remove: str, kind: int) -> tuple[bool, bool]:
    # real: to_remove
    is_expected_type: bool = kind == 0
    if not is_expected_type:
        return (is_expected_type, False)

    if "vlan_id" in to_remove:
        return (is_expected_type, True)
    return (is_expected_type, False)


def main() -> None:
    to_remove: str = nondet_str()
    kind: int = nondet_int()
    __ESBMC_assume(abs(kind) <= 1073741824)

    result = slice_model(to_remove, kind)
    assert result[0]


main()
